import { FilterX, ListFilter } from 'lucide-react';
import { useMemo, useState } from 'react';
import { getStoryFiltersFromCode } from '@nao/shared/story-segments';
import type { ParsedFilterBlock } from '@nao/shared/story-segments';

import type { QueryDataMap } from './story-embeds';
import { Button } from '@/components/ui/button';
import {
	DropdownMenu,
	DropdownMenuCheckboxItem,
	DropdownMenuContent,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

export type StoryFilterSelection = string | string[];

export function StoryFilterBar({ code, queryData }: { code: string; queryData?: QueryDataMap | null }) {
	const filters = useMemo(() => dedupeFilters(getStoryFiltersFromCode(code)), [code]);
	const [selections, setSelections] = useState<Record<string, StoryFilterSelection>>({});

	if (filters.length === 0) {
		return null;
	}

	const setSelection = (filterId: string, selection: StoryFilterSelection) =>
		setSelections((current) => ({ ...current, [filterId]: selection }));

	const hasActiveFilters = Object.values(selections).some((selection) =>
		typeof selection === 'string' ? Boolean(selection) : selection.some(Boolean),
	);

	return (
		<div className='flex flex-wrap items-end gap-3 rounded-lg border bg-muted/20 p-3'>
			<div className='flex h-8 items-center gap-2 text-sm font-medium text-muted-foreground'>
				<ListFilter className='size-4' />
				Filters
			</div>
			{filters.map((filter) => (
				<StoryFilterControl
					key={filter.id}
					filter={filter}
					selection={selections[filter.id]}
					onChange={(selection) => setSelection(filter.id, selection)}
					queryData={queryData}
				/>
			))}
			{hasActiveFilters && (
				<Button variant='ghost' size='sm' className='h-8 gap-1.5' onClick={() => setSelections({})}>
					<FilterX className='size-3.5' />
					Clear
				</Button>
			)}
		</div>
	);
}

function StoryFilterControl({
	filter,
	selection,
	onChange,
	queryData,
}: {
	filter: ParsedFilterBlock;
	selection: StoryFilterSelection | undefined;
	onChange: (selection: StoryFilterSelection) => void;
	queryData?: QueryDataMap | null;
}) {
	const options = useFilterOptions(filter, queryData);

	return (
		<label className='flex min-w-36 flex-col gap-1'>
			<span className='text-xs font-medium text-muted-foreground'>{filter.label}</span>
			{filter.filterType === 'select' ? (
				<Select
					value={typeof selection === 'string' && selection ? selection : '__all__'}
					onValueChange={(value) => onChange(value === '__all__' ? '' : value)}
				>
					<SelectTrigger className='h-8 min-w-36 bg-background'>
						<SelectValue placeholder='All' />
					</SelectTrigger>
					<SelectContent>
						<SelectItem value='__all__'>All</SelectItem>
						{options.map((option) => (
							<SelectItem key={option} value={option}>
								{option}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			) : filter.filterType === 'multi_select' ? (
				<MultiSelectFilter
					options={options}
					value={Array.isArray(selection) ? selection : []}
					onChange={onChange}
				/>
			) : filter.filterType === 'date_range' || filter.filterType === 'number_range' ? (
				<RangeFilter
					type={filter.filterType === 'date_range' ? 'date' : 'number'}
					value={Array.isArray(selection) ? selection : []}
					onChange={onChange}
				/>
			) : (
				<Input
					type='search'
					className='h-8 min-w-44 bg-background'
					placeholder='Search'
					value={typeof selection === 'string' ? selection : ''}
					onChange={(event) => onChange(event.target.value)}
				/>
			)}
		</label>
	);
}

function MultiSelectFilter({
	options,
	value,
	onChange,
}: {
	options: string[];
	value: string[];
	onChange: (value: string[]) => void;
}) {
	return (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button variant='outline' size='sm' className='h-8 min-w-36 justify-between bg-background font-normal'>
					{value.length > 0 ? `${value.length} selected` : 'All'}
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent className='max-h-64 min-w-48'>
				{options.map((option) => (
					<DropdownMenuCheckboxItem
						key={option}
						checked={value.includes(option)}
						onSelect={(event) => event.preventDefault()}
						onCheckedChange={(checked) =>
							onChange(checked ? [...value, option] : value.filter((candidate) => candidate !== option))
						}
					>
						{option}
					</DropdownMenuCheckboxItem>
				))}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

function RangeFilter({
	type,
	value,
	onChange,
}: {
	type: 'date' | 'number';
	value: string[];
	onChange: (value: string[]) => void;
}) {
	return (
		<div className='flex items-center gap-1'>
			<Input
				type={type}
				className='h-8 w-36 bg-background'
				value={value[0] ?? ''}
				onChange={(event) => onChange([event.target.value, value[1] ?? ''])}
				aria-label='Minimum'
			/>
			<span className='text-xs text-muted-foreground'>to</span>
			<Input
				type={type}
				className='h-8 w-36 bg-background'
				value={value[1] ?? ''}
				onChange={(event) => onChange([value[0] ?? '', event.target.value])}
				aria-label='Maximum'
			/>
		</div>
	);
}

function useFilterOptions(filter: ParsedFilterBlock, queryData?: QueryDataMap | null): string[] {
	return useMemo(() => {
		if (!queryData) {
			return [];
		}
		const values = Object.values(queryData).flatMap((result) => distinctColumnValues(result.data, filter.column));
		return [...new Set(values)].sort((a, b) => a.localeCompare(b));
	}, [queryData, filter.column]);
}

function distinctColumnValues(rows: Record<string, unknown>[], column: string): string[] {
	const normalizedColumn = column.toLocaleLowerCase();
	return rows.flatMap((row) => {
		const key = Object.keys(row).find((candidate) => candidate.toLocaleLowerCase() === normalizedColumn);
		const value = key ? row[key] : undefined;
		return value === null || value === undefined ? [] : [String(value)];
	});
}

function dedupeFilters(filters: ParsedFilterBlock[]): ParsedFilterBlock[] {
	const seen = new Set<string>();
	return filters.filter((filter) => {
		if (seen.has(filter.id)) {
			return false;
		}
		seen.add(filter.id);
		return true;
	});
}

